    "category": "database",
    "parameters": [
      {
        "name": "toolType",
        "type": "select",
        "required": true,
        "description": "Type of Ensembl operation to perform",
        "options": [
          "species",
          "sequence",
          "gene",
          "variation",
          "homology",
          "xref",
          "phenotype",
          "ontology",
          "map"
