      },
      {
        "name": "region",
        "type": "string",
        "required": false,
        "description": "Genomic region to lift over, for toolType=map",
        "placeholder": "17:7579472-7579473",
        "showWhen": {
          "parameter": "toolType",
          "value": "map"
        }
      },
      {
        "name": "sourceAssembly",
        "type": "string",
        "required": false,
        "description": "Assembly the coordinates are currently in (GRCh37/hg19 or GRCh38/hg38)",
        "placeholder": "GRCh37",
        "showWhen": {
          "parameter": "toolType",
          "value": "map"
        }
      },
      {
        "name": "targetAssembly",
        "type": "string",
