      },
      {
        "name": "species",
        "type": "string",
        "required": false,
        "description": "Species name (e.g., homo_sapiens, mus_musculus)",
        "placeholder": "e.g., homo_sapiens, mus_musculus, danio_rerio",
        "showWhen": {
          "parameter": "toolType",
          "value": [
            "gene",
            "variation",
            "homology",
            "xref",
            "phenotype"
          ]
        }
      },
      {
        "name": "division",
        "type": "select",
        "required": false,
        "description": "Ensembl division to query",
        "options": [
          "EnsemblVertebrates",
          "EnsemblBacteria",
          "EnsemblFungi",
          "EnsemblMetazoa",
          "EnsemblPlants",
