          "parameter": "toolType",
          "value": [
            "sequence",
            "gene",
            "variation",
            "homology",
            "xref"
          ]
        }
      },
      {
        "name": "symbol",
        "type": "string",
        "required": false,
        "description": "Gene symbol or name",
        "placeholder": "e.g., BRCA1, TP53, EGFR",
        "showWhen": {
          "parameter": "toolType",
          "value": [
            "gene",
            "homology",
            "xref"
          ]
        }
      },
      {
        "name": "external_name",
        "type": "string",
        "required": false,
        "description": "External gene name",
        "placeholder": "e.g., tumor protein p53",
        "showWhen": {
          "parameter": "toolType",
          "value": "gene"
        }
      },
      {
        "name": "biotype",
        "type": "select",
        "required": false,
        "description": "Gene biotype filter",
        "options": [
          "protein_coding",
          "lncRNA",
          "miRNA",
          "rRNA",
          "tRNA",
          "snRNA",
          "snoRNA",
          "pseudogene"
        ],
        "showWhen": {
          "parameter": "toolType",
          "value": "gene"
        }
      },
      {
        "name": "expand_3prime",
        "type": "number",
        "required": false,
        "description": "Expand sequence 3' end by N bases",
        "min": 0,
        "max": 10000,
        "defaultValue": 0,
        "showWhen": {
          "parameter": "toolType",
          "value": "sequence"
        }
      },
      {
        "name": "expand_5prime",
        "type": "number",
        "required": false,
        "description": "Expand sequence 5' end by N bases",
        "min": 0,
        "max": 10000,
        "defaultValue": 0,
        "showWhen": {
          "parameter": "toolType",
          "value": "sequence"
        }
      },
      {
        "name": "type",
        "type": "select",
        "required": false,
        "description": "Homology type",
        "options": [
          "orthologues",
          "paralogues",
          "projections",
          "all"
        ],
        "defaultValue": "all",
        "showWhen": {
          "parameter": "toolType",
          "value": "homology"
        }
      },
      {
        "name": "target_species",
        "type": "string",
        "required": false,
        "description": "Target species for homology search",
        "placeholder": "e.g., mus_musculus, rattus_norvegicus",
        "showWhen": {
          "parameter": "toolType",
          "value": "homology"
        }
      },
      {
        "name": "external_db",
        "type": "select",
        "required": false,
        "description": "External database for cross-references",
        "options": [
          "HGNC",
          "UniProtKB/Swiss-Prot",
          "UniProtKB/TrEMBL",
          "RefSeq_mRNA",
          "RefSeq_peptide",
          "UCSC",
          "OMIM",
          "WikiGene"
        ],
        "showWhen": {
          "parameter": "toolType",
          "value": "xref"
        }
      },
      {
        "name": "term",
        "type": "string",
        "required": false,
        "description": "Phenotype term to search",
        "placeholder": "e.g., breast cancer, diabetes",
        "showWhen": {
          "parameter": "toolType",
          "value": "phenotype"
        }
      },
      {
        "name": "gene",
        "type": "string",
        "required": false,
        "description": "Gene for phenotype search",
        "placeholder": "e.g., BRCA1, TP53",
        "showWhen": {
          "parameter": "toolType",
          "value": "phenotype"
        }
      },
      {
        "name": "name",
        "type": "string",
        "required": false,
        "description": "Ontology name",
        "placeholder": "e.g., GO, HPO, MONDO",
        "showWhen": {
          "parameter": "toolType",
          "value": "ontology"
        }
      },
      {
        "name": "relation",
        "type": "select",
        "required": false,
        "description": "Ontology relation type",
        "options": [
          "part_of",
          "is_a",
